<?php
namespace App\Http\Controllers;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Validation\Rule;class UserController extends Controller{public function index(Request $r){return User::with('section')->when($r->filled('search'),function($q)use($r){$t='%'.$r->query('search').'%';$q->where(fn($w)=>$w->where('name','like',$t)->orWhere('email','like',$t)->orWhere('role','like',$t));})->orderBy('name')->paginate(30);}public function updateRole(Request $r,User $user){$d=$r->validate(['role'=>['required',Rule::in(['admin','teacher','student'])]]);if($user->id===$r->user()->id&&$d['role']!=='admin')return response()->json(['message'=>'You cannot remove your own admin role.'],422);$user->update($d);return $user->fresh()->load('section');}}
